itle": "10 · Học không giám sát và K-means", "resource_id": 733, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg", "resource_title": "Python cơ bản - HowKteam"}, {"course_id": 53, "lesson_id": 204, "lesson_order": 2, "lesson_title": "01 · Python nền tảng", "resource_id": 653, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 205, "lesson_order": 3, "lesson_title": "02 · BFS, DFS, UCS và giới hạn sâu", "resource_id": 662, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 206, "lesson_order": 4, "lesson_title": "03 · Heuristic, AKT và A*", "resource_id": 671, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 207, "lesson_order": 5, "lesson_title": "04 · Leo đồi và thuật toán di truyền", "resource_id": 680, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 208, "lesson_order": 6, "lesson_title": "05 · Minimax và alpha-beta", "resource_id": 689, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 209, "lesson_order": 7, "lesson_title": "06 · GTS và tô màu đồ thị", "resource_id": 698, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 210, "lesson_order": 8, "lesson_title": "07 · Logic mệnh đề, Vương Hạo và Robinson", "resource_id": 707, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}, {"course_id": 53, "lesson_id": 211, "lesson_order": 9, "lesson_title": "08 · Luật sinh và mạng ngữ nghĩa", "resource_id": 716, "old_url": "https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_", "resource_title": "Machine learning cơ bản với Python - HowKteam"}]$DATA$::jsonb) LOOP
  SELECT l.title,r.resource_url,r.resource_type INTO actual_title,actual_url,actual_type
  FROM lms.lessons l JOIN lms.lesson_resources r ON r.lesson_id=l.lesson_id
  WHERE l.course_id=(v->>'course_id')::int AND l.lesson_id=(v->>'lesson_id')::int
    AND l.lesson_order=(v->>'lesson_order')::int AND l.is_published AND NOT l.is_deleted
    AND r.resource_id=(v->>'resource_id')::bigint;
  IF NOT FOUND THEN
    -- Idempotent if URL was deleted in an earlier successful run.
    IF NOT EXISTS(SELECT 1 FROM lms.lesson_resources WHERE resource_id=(v->>'resource_id')::bigint)
    THEN CONTINUE; END IF;
    RAISE EXCEPTION 'Course/lesson/resource mismatch at resource %',v->>'resource_id';
  END IF;
  IF btrim(regexp_replace(actual_title,'[[:space:]]+',' ','g')) IS DISTINCT FROM (v->>'lesson_title')
  THEN RAISE EXCEPTION 'Lesson title mismatch: % (% vs %)',v->>'lesson_id',actual_title,v->>'lesson_title'; END IF;
  IF actual_type<>'LINK' OR actual_url IS DISTINCT FROM v->>'old_url'
  THEN RAISE EXCEPTION 'Resource type or URL mismatch for resource %',v->>'resource_id'; END IF;
  SELECT count(*) INTO nleft FROM lms.lesson_resources r
    WHERE r.lesson_id=(v->>'lesson_id')::int AND r.resource_id<>(v->>'resource_id')::bigint
    AND r.resource_type IN ('VIDEO','LINK')
    AND (r.resource_url ILIKE '%youtube.com/%' OR r.resource_url ILIKE '%youtu.be/%');
  IF nleft=0 THEN RAISE EXCEPTION 'Would remove last YouTube source of lesson %',v->>'lesson_id'; END IF;
  DELETE FROM lms.lesson_resources WHERE resource_id=(v->>'resource_id')::bigint AND resource_url=v->>'old_url' AND resource_type='LINK';
  GET DIAGNOSTICS c=ROW_COUNT;
  IF c<>1 THEN RAISE EXCEPTION 'Delete failed resource %',v->>'resource_id'; END IF;
  n:=n+1;
 END LOOP;
 RAISE NOTICE 'Removed % clearly mismatched supplemental YouTube LINK resources. VIDEO records unchanged.',n;
END $clean$;
COMMIT;
